def distinctSubsequences(S):
    n = len(S)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1, -1, -1):
        for j in range(i+1, n):
            dp[i][j] = dp[i][j-1] + dp[i+1][j]
            if S[i] == S[j]:
                dp[i][j] += dp[i+1][j-1]
    return sum(dp[0]) % (10**9 + 7)
```
